#[inline]
pub const fn RDMA_NL_GET_CLIENT(type_: i32) -> i32 { (type_ & (((1 << 6) - 1) << 10)) >> 10 }
#[inline]
pub const fn RDMA_NL_GET_OP(type_: i32) -> i32 { type_ & ((1 << 10) - 1) }
#[inline]
pub const fn RDMA_NL_GET_TYPE(client: i32, op: i32) -> i32 { (client << 10) + op }

